#include <stdio.h>

int main() {
    int N, R;
    scanf("%d %d", &N, &R);

    int colors[N];
    int redCount = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &colors[i]);
        if (colors[i] == 1) redCount++;
    }

    // Check if redCount matches given R
    if (redCount != R) {
        printf("NO\n");
        return 0;
    }

    // Check that position i should have color same as number (i+1)'s color
    // We need to know which numbers are red.
    // Build array numberColor[1..N] where numberColor[x] = color of number x
    int numberColor[N+1];
    for (int i = 0; i < N; i++) {
        numberColor[i+1] = colors[i];
    }

    for (int i = 0; i < N; i++) {
        if (colors[i] != numberColor[i+1]) {
            printf("NO\n");
