int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        int N, R;
        scanf("%d %d", &N, &R);
        int a[N+1];
        for (int i = 1; i <= N; i++) scanf("%d", &a[i]);

        int visited[N+1];
        memset(visited, 0, sizeof(visited));

        int cycles[N+1], nc = 0;
        for (int i = 1; i <= N; i++) {
            if (!visited[i]) {
                int len = 0, j = i;
                while (!visited[j]) {
                    visited[j] = 1;
                    j = a[j];
                    len++;
                }
                cycles[nc++] = len;
            }
        }

        // Subset sum: can we pick subset of cycles with total size R?
        int dp[N+1];
        memset(dp, 0, sizeof(dp));
        dp[0] = 1;
        for (int i = 0; i < nc; i++) {
            for (int j = N; j >= cycles[i]; j--) {
                if (dp[j - cycles[i]]) dp[j] = 1;
            }
        }

        printf("%s\n", dp[R] ? "Yes" : "No");
    }
    return 0;
}

