public class TwoColorsSort {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int R = Integer.parseInt(st.nextToken());

        int[] p = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            p[i] = Integer.parseInt(st.nextToken()) - 1;
        }

        String colors = br.readLine().trim();
        int[] color = new int[N]; // 0 for red, 1 for blue
        for (int i = 0; i < N; i++) {
            color[i] = (colors.charAt(i) == 'R') ? 0 : 1;
        }

        boolean[] visited = new boolean[N];

        for (int i = 0; i < N; i++) {
            if (!visited[i]) {
                List<Integer> cycle = new ArrayList<>();
                int cur = i;
                while (!visited[cur]) {
                    visited[cur] = true;
                    cycle.add(cur);
                    cur = p[cur];
                }

                if (cycle.size() == 1) continue;

                boolean hasRed = false, hasBlue = false;
                for (int idx : cycle) {
                    if (color[idx] == 0) hasRed = true;
                    else hasBlue = true;
                }

                if (!hasRed || !hasBlue) {
                    System.out.println("NO");
                    return;
                }
            }
        }
        System.out.println("YES");
    }
}

