import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int T = fs.nextInt();
        while (T-- > 0) {
            int N = fs.nextInt();
            int R = fs.nextInt();

            int[] p = new int[N + 1];
            boolean[] vis = new boolean[N + 1];

            for (int i = 1; i <= N; i++) {
                p[i] = fs.nextInt();
            }

            int cycles = 0;
            for (int i = 1; i <= N; i++) {
                if (!vis[i]) {
                    cycles++;
                    int cur = i;
                    while (!vis[cur]) {
                        vis[cur] = true;
                        cur = p[cur];
                    }
                }
            }

            // Minimum red needed = number of non-fixed positions in cycles = N - cycles
            // Any larger number up to N is possible, because in each cycle of length L,
            // we may color either all L positions blue, or any number from 2..L red.
            // Hence all totals >= N-cycles are achievable except exactly N-cycles+1.
            // But since each cycle contributes (L-1) minimum red, adding 1 is possible
            // iff there exists a cycle length >= 3. More generally, achievable totals
            // are all sums where in each cycle extra red can be 0 or 1..(L-2).
            //
            // This simplifies to checking by DP over cycle extra capacities.

            ArrayList<Integer> extras = new ArrayList<>();
            Arrays.fill(vis, false);
            for (int i = 1; i <= N; i++) {
                if (!vis[i]) {
                    int cur = i, len = 0;
                    while (!vis[cur]) {
                        vis[cur] = true;
                        cur = p[cur];
                        len++;
                    }
                    if (len >= 2) extras.add(len - 2);
                }
            }

            int minRed = N - cycles;
            int needExtra = R - minRed;

            boolean possible;
            if (needExtra < 0) {
                possible = false;
            } else {
                int totalExtra = 0;
                for (int x : extras) totalExtra += x;

                if (needExtra > totalExtra) {
                    possible = false;
                } else {
                    // subset-sum with groups allowing contribution 0..x for each cycle
                    boolean[] dp = new boolean[needExtra + 1];
                    dp[0] = true;

                    for (int cap : extras) {
                        boolean[] ndp = new boolean[needExtra + 1];
                        int window = 0;
                        for (int s = 0; s <= needExtra; s++) {
                            if (dp[s]) window++;
                            if (s - cap - 1 >= 0 && dp[s - cap - 1]) window--;
                            ndp[s] = window > 0;
                        }
                        dp = ndp;
                    }
                    possible = dp[needExtra];
                }
            }

            out.append(possible ? "YES" : "NO").append('\n');
        }

        System.out.print(out);
    }
}
